run_challenge() {
    local RUN_FLAGS=(--experimental-wasm-exnref --turboshaft-wasm)
    local filename="$1"
    tempfile=$(mktemp)
    if [ ! -e "$tempfile" ]; then
        echo "Error: Failed to create temporary file."
        exit 1
    fi

    cp "$filename" "$tempfile"
    if [ $? -ne 0 ]; then
        echo "Error: Failed to copy the file to the temporary file."
        exit 1
    fi

    chmod 644 "$tempfile"
    /challenge/d8 "${RUN_FLAGS[@]}" "$tempfile"
    rm "$tempfile"
}

su -s /bin/bash -c "$(declare -f run_challenge); run_challenge \"$filename\"" nobody

